// PLAT-21: the SDK's CLI commands (create, build, from-openapi, create-multi-resource, add-resource) and the key-pair
// script (build/internal/util/jwe/cli.mjs). Standalone script (no mocha). Every command runs as a child process
// in a fresh temporary directory; `yarn` is replaced by a stub on PATH that only records its arguments, so nothing is
// installed and no network call is made. Keys are generated by the commands under test and exist only in the
// temporary directory, which is removed at the end.
// Tests marked "pins current behaviour" fix it as it is now, so a deliberate change to it updates the test with it.
import crypto from 'node:crypto';
import {spawnSync} from 'node:child_process';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import {fileURLToPath} from 'node:url';
import {assert, assertEqual, suite} from './helpers/mini.mjs';

const {test, finish} = suite('CLI commands');

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const CLI = path.join(root, 'build/cli.mjs');
const JWE_CLI = path.join(root, 'build/internal/util/jwe/cli.mjs');
const TEMPLATE = path.join(root, 'template/connector');
const base = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'sdk-cli-')));
let counter = 0;

const SPEC = {
  openapi: '3.0.0',
  info: {title: 'Pets', version: '1.0.0'},
  servers: [{url: 'https://api.example.com/v1'}],
  paths: {
    '/pets': {
      get: {operationId: 'listPets', summary: 'List pets', responses: {200: {description: 'ok'}}},
      post: {
        operationId: 'createPet',
        summary: 'Create a pet',
        requestBody: {content: {'application/json': {schema: {type: 'object', properties: {name: {type: 'string'}}}}}},
        responses: {201: {description: 'ok'}},
      },
    },
    '/pets/{id}': {
      get: {
        operationId: 'getPet',
        summary: 'Get a pet',
        parameters: [{name: 'id', in: 'path', required: true, schema: {type: 'string'}}],
        responses: {200: {description: 'ok'}},
      },
    },
  },
};
const OWNERS = {
  openapi: '3.0.0',
  info: {title: 'Owners', version: '1.0.0'},
  servers: [{url: 'https://owners.example.com'}],
  paths: {
    '/owners': {get: {operationId: 'listOwners', summary: 'List owners', responses: {200: {description: 'ok'}}}},
  },
};
const SPEC_YAML = `openapi: 3.0.0
info:
  title: Yaml
  version: 1.0.0
servers:
  - url: https://yaml.example.com
paths:
  /things:
    get:
      operationId: listThings
      summary: List things
      responses:
        '200':
          description: ok
`;

// a fresh sandbox: work/ is the working directory, specs/ holds specification files, bin/yarn is the stub
const sandbox = () => {
  const dir = path.join(base, `t${++counter}`);
  const work = path.join(dir, 'work');
  const bin = path.join(dir, 'bin');
  const specs = path.join(dir, 'specs');
  const yarnLog = path.join(dir, 'yarn.log');
  for (const d of [work, bin, specs]) fs.mkdirSync(d, {recursive: true});
  fs.writeFileSync(path.join(bin, 'yarn'), '#!/bin/sh\necho "$PWD|$*" >> "$YARN_LOG"\nexit "${YARN_EXIT:-0}"\n', {mode: 0o755});
  fs.writeFileSync(path.join(specs, 'pets.json'), JSON.stringify(SPEC));
  fs.writeFileSync(path.join(specs, 'owners.json'), JSON.stringify(OWNERS));
  fs.writeFileSync(path.join(specs, 'things.yaml'), SPEC_YAML);
  const env = {...process.env, PATH: `${bin}${path.delimiter}${process.env.PATH}`, YARN_LOG: yarnLog};
  const sb = {
    dir,
    work,
    specs,
    spec: (name) => path.join(specs, name),
    yarnCalls: () => (fs.existsSync(yarnLog) ? fs.readFileSync(yarnLog, 'utf8').trim().split('\n') : []),
    cli: (args, extraEnv = {}, cwd = work) => {
      const r = spawnSync(process.execPath, [CLI, ...args], {cwd, encoding: 'utf8', env: {...env, ...extraEnv}, timeout: 60000});
      return {code: r.status, out: r.stdout, err: r.stderr};
    },
    read: (rel) => fs.readFileSync(path.join(work, rel), 'utf8'),
    exists: (rel) => fs.existsSync(path.join(work, rel)),
  };
  return sb;
};

const tree = (dir, rel = '') =>
  fs
    .readdirSync(path.join(dir, rel), {withFileTypes: true})
    .flatMap((e) => (e.isDirectory() ? tree(dir, path.join(rel, e.name)) : [path.join(rel, e.name)]))
    .sort();
const tpl = (rel) => fs.readFileSync(path.join(TEMPLATE, rel), 'utf8');
const envLines = (text) => text.split('\n');
const BASE64 = /^[A-Za-z0-9+/]+=*$/;

// parse a base64 key pair with node:crypto; both keys must be well formed and belong together
const checkKeyPair = (privateB64, publicB64) => {
  assert(BASE64.test(privateB64), 'the private key is one base64 string');
  assert(BASE64.test(publicB64), 'the public key is one base64 string');
  const priv = crypto.createPrivateKey(Buffer.from(privateB64, 'base64').toString('utf8'));
  assertEqual(priv.type, 'private', 'private key type');
  const pub = crypto.createPublicKey(Buffer.from(publicB64, 'base64').toString('utf8'));
  assertEqual(pub.type, 'public', 'public key type');
  const spki = (k) => k.export({type: 'spki', format: 'pem'});
  assertEqual(spki(crypto.createPublicKey(priv)), spki(pub), 'the public key belongs to the private key');
  return {priv, pub};
};
const keysFromEnv = (text) => {
  const lines = envLines(text);
  assertEqual(lines.length, 4, 'env has three lines and a final newline');
  assertEqual(lines[0], 'REGISTRATION_TOKEN=', 'registration token is empty');
  assert(lines[1].startsWith('PRIVATE_KEY='), 'second line is the private key');
  assert(lines[2].startsWith('PUBLIC_KEY='), 'third line is the public key');
  assertEqual(lines[3], '', 'final newline');
  return checkKeyPair(lines[1].slice('PRIVATE_KEY='.length), lines[2].slice('PUBLIC_KEY='.length));
};

const PROJECT_FILES = [
  '.env',
  '.gitignore',
  'Containerfile',
  'entrypoint.sh',
  'package.json',
  'src/controller/index.mts',
  'src/index.mts',
  'tsconfig.json',
];

