// --- build ---

// the layout of a connector project with the SDK installed: the CLI finds package.json and logo.png five folders above its
// build/builder folder, which is the project folder
const buildProject = (sb, {logo = true} = {}) => {
  const p = sb.work;
  const sdk = path.join(p, 'node_modules/@aloma.io/integration-sdk');
  fs.mkdirSync(sdk, {recursive: true});
  fs.cpSync(path.join(root, 'build'), path.join(sdk, 'build'), {recursive: true});
  fs.copyFileSync(path.join(root, 'package.json'), path.join(sdk, 'package.json'));
  fs.symlinkSync(path.join(root, 'node_modules'), path.join(sdk, 'node_modules'));
  fs.writeFileSync(path.join(p, 'package.json'), JSON.stringify({name: 'p', version: '1.2.3', connectorId: 'c-9', type: 'module'}));
  fs.copyFileSync(path.join(TEMPLATE, 'tsconfig.json'), path.join(p, 'tsconfig.json'));
  fs.mkdirSync(path.join(p, 'src/controller'), {recursive: true});
  fs.copyFileSync(path.join(TEMPLATE, 'src/controller/index.mts'), path.join(p, 'src/controller/index.mts'));
  fs.mkdirSync(path.join(p, 'build'));
  fs.writeFileSync(path.join(p, 'build/old.txt'), 'old');
  if (logo) fs.writeFileSync(path.join(p, 'logo.png'), 'PNGDATA');
  return path.join(sdk, 'build/cli.mjs');
};
const runBuild = (sb, cli) => {
  const r = spawnSync(process.execPath, [cli, 'build'], {cwd: sb.work, encoding: 'utf8', timeout: 60000});
  return {code: r.status, out: r.stdout, err: r.stderr};
};

await test('build empties the build folder and writes .controller.json with the method list, connector id and version', async () => {
  const sb = sandbox();
  const cli = buildProject(sb);
  const r = runBuild(sb, cli);
  assertEqual(r.code, 0, `exit code (${r.err})`);
  assert(!sb.exists('build/old.txt'), 'old build file is gone');
  const data = JSON.parse(sb.read('build/.controller.json'));
  assertEqual(Object.keys(data), ['text', 'methods', 'connectorId', 'version'], 'keys');
  assertEqual(data.methods, ['hello'], 'methods');
  assertEqual(data.connectorId, 'c-9', 'connector id');
  assertEqual(data.version, '1.2.3', 'version');
  assert(data.text.includes('declare function hello()'), 'declaration text');
});

