// --- the jwe key-pair script ---

const keyScript = () => {
  const r = spawnSync(process.execPath, [JWE_CLI], {encoding: 'utf8', timeout: 60000});
  return {code: r.status, out: r.stdout, err: r.stderr};
};

await test('the key-pair script exits 0 and prints exactly two lines, PRIVATE_KEY=<base64> and PUBLIC_KEY=<base64>', async () => {
  const r = keyScript();
  assertEqual(r.code, 0, `exit code (${r.err})`);
  const lines = r.out.split('\n');
  assertEqual(lines.length, 3, 'two lines and a final newline');
  assertEqual(lines[2], '', 'final newline');
  assert(lines[0].startsWith('PRIVATE_KEY='), 'first line');
  assert(lines[1].startsWith('PUBLIC_KEY='), 'second line');
});

await test('the key-pair script prints a private and a public key that node:crypto parses, and the pair matches', async () => {
  const lines = keyScript().out.split('\n');
  const {priv, pub} = checkKeyPair(lines[0].slice('PRIVATE_KEY='.length), lines[1].slice('PUBLIC_KEY='.length));
  assertEqual(priv.asymmetricKeyType, 'rsa', 'private key algorithm');
  assertEqual(pub.asymmetricKeyType, 'rsa', 'public key algorithm');
  assertEqual(priv.asymmetricKeyDetails.modulusLength, 2048, 'modulus length');
});

await test('the key-pair script prints a different pair on every run', async () => {
  assert(keyScript().out !== keyScript().out, 'outputs differ');
});

await test('the key-pair script prints keys in the format create writes to the .env', async () => {
  const sb = sandbox();
  sb.cli(['create', 'my-conn', '--connector-id', 'c']);
  const fromEnv = envLines(sb.read('my-conn/.env'));
  const fromScript = keyScript().out.split('\n');
  assertEqual(fromScript[0].length, fromEnv[1].length, 'private key line length');
  assertEqual(fromScript[1].length, fromEnv[2].length, 'public key line length');
});

fs.rmSync(base, {recursive: true, force: true});
finish();
